def _extract_pval(raw):
    """Extract a scalar p-value regardless of whether it is a number or a dict."""
    if raw is None:
        return float('nan')
    if isinstance(raw, dict):
        # try common sub-keys from the repasca implementation
        for key in ('pvalue', 'p_value', 'p', 'Pvalue', 'P'):
            if key in raw:
                return float(np.squeeze(raw[key]))
        # last resort: take the first numeric leaf
        for v in raw.values():
            try:
                return float(np.squeeze(v))
            except Exception:
                pass
        return float('nan')
    try:
        return float(np.squeeze(raw))
    except Exception:
        return float('nan')

print(f"{'Effect':&lt;12} {'SSQ':&gt;10} {'Expl. var (%)':&gt;14} {'p-value':&gt;9}")
print('─' * 50)
for ek in effect_keys:
    eff  = model[ek]
    ssq  = float(np.squeeze(eff.get('EffectSSQ',     np.nan)))
    ev   = float(np.squeeze(eff.get('EffectExplVar', np.nan)))
    pval = _extract_pval(eff.get('EffectSignif'))
    star = ' *' if pval &lt;= 0.05 else ''
    print(f"{ek:&lt;12} {ssq:&gt;10.2f} {ev:&gt;13.2f}% {pval:&gt;9.3f}{star}")

sig = model.get('SignificantTerms', [])
print(f"\nSignificant effects (p ≤ 0.05): {sig if sig else 'none'}")

